        [Fact]
        public void JapaneseHydrometerScale_QuantityInfo_ReturnsQuantityInfoDescribingQuantity()
        {
            JapaneseHydrometerScaleUnit[] unitsOrderedByName = EnumHelper.GetValues<JapaneseHydrometerScaleUnit>().OrderBy(x => x.ToString(), StringComparer.OrdinalIgnoreCase).ToArray();
            var quantity = new JapaneseHydrometerScale(1, JapaneseHydrometerScaleUnit.ReciprocalSpecificGravity);

            QuantityInfo<JapaneseHydrometerScale, JapaneseHydrometerScaleUnit> quantityInfo = quantity.QuantityInfo;

            Assert.Equal("JapaneseHydrometerScale", quantityInfo.Name);
            Assert.Equal(JapaneseHydrometerScale.Zero, quantityInfo.Zero);
            Assert.Equal(JapaneseHydrometerScale.BaseUnit, quantityInfo.BaseUnitInfo.Value);
            Assert.Equal(unitsOrderedByName, quantityInfo.Units);
            Assert.Equal(unitsOrderedByName, quantityInfo.UnitInfos.Select(x => x.Value));
            Assert.Equal(JapaneseHydrometerScale.Info, quantityInfo);
            Assert.Equal(quantityInfo, ((IQuantity)quantity).QuantityInfo);
            Assert.Equal(quantityInfo, ((IQuantity<JapaneseHydrometerScaleUnit>)quantity).QuantityInfo);
        }

        [Fact]
