                JapaneseHydrometerScale convertedQuantity = quantity.ToUnit(UnitSystem.SI);

                Assert.Equal(JapaneseHydrometerScaleUnit.ReciprocalSpecificGravity, convertedQuantity.Unit);
                Assert.Equal(quantity.Value, convertedQuantity.Value);
            }, () =>
