        [Fact]
        public void ConversionRoundTrip()
        {
            JapaneseHydrometerScale reciprocalspecificgravity = JapaneseHydrometerScale.FromReciprocalSpecificGravities(3);
            Assert.Equal(3, JapaneseHydrometerScale.FromDegreesBaumeHeavy(reciprocalspecificgravity.DegreesBaumeHeavy).ReciprocalSpecificGravities);
            Assert.Equal(3, JapaneseHydrometerScale.FromDegreesBaumeLight(reciprocalspecificgravity.DegreesBaumeLight).ReciprocalSpecificGravities);
            Assert.Equal(3, JapaneseHydrometerScale.FromReciprocalSpecificGravities(reciprocalspecificgravity.ReciprocalSpecificGravities).ReciprocalSpecificGravities);
            Assert.Equal(3, JapaneseHydrometerScale.FromSakeMeterValues(reciprocalspecificgravity.SakeMeterValues).ReciprocalSpecificGravities);
        }

        [Fact]
        public void ArithmeticOperators()
        {
            JapaneseHydrometerScale v = JapaneseHydrometerScale.FromReciprocalSpecificGravities(1);
            Assert.Equal(-1, -v.ReciprocalSpecificGravities);
            Assert.Equal(2, (JapaneseHydrometerScale.FromReciprocalSpecificGravities(3) - v).ReciprocalSpecificGravities);
            Assert.Equal(2, (v + v).ReciprocalSpecificGravities);
            Assert.Equal(10, (v * 10).ReciprocalSpecificGravities);
            Assert.Equal(10, (10 * v).ReciprocalSpecificGravities);
            Assert.Equal(2, (JapaneseHydrometerScale.FromReciprocalSpecificGravities(10) / 5).ReciprocalSpecificGravities);
            Assert.Equal(2, JapaneseHydrometerScale.FromReciprocalSpecificGravities(10) / JapaneseHydrometerScale.FromReciprocalSpecificGravities(5));
        }

        [Fact]
        public void ComparisonOperators()
        {
            JapaneseHydrometerScale oneReciprocalSpecificGravity = JapaneseHydrometerScale.FromReciprocalSpecificGravities(1);
            JapaneseHydrometerScale twoReciprocalSpecificGravities = JapaneseHydrometerScale.FromReciprocalSpecificGravities(2);

            Assert.True(oneReciprocalSpecificGravity < twoReciprocalSpecificGravities);
            Assert.True(oneReciprocalSpecificGravity <= twoReciprocalSpecificGravities);
            Assert.True(twoReciprocalSpecificGravities > oneReciprocalSpecificGravity);
            Assert.True(twoReciprocalSpecificGravities >= oneReciprocalSpecificGravity);

            Assert.False(oneReciprocalSpecificGravity > twoReciprocalSpecificGravities);
            Assert.False(oneReciprocalSpecificGravity >= twoReciprocalSpecificGravities);
            Assert.False(twoReciprocalSpecificGravities < oneReciprocalSpecificGravity);
            Assert.False(twoReciprocalSpecificGravities <= oneReciprocalSpecificGravity);
        }

