        [Theory]
        [InlineData(1, JapaneseHydrometerScaleUnit.ReciprocalSpecificGravity, 1, JapaneseHydrometerScaleUnit.ReciprocalSpecificGravity, true)]  // Same value and unit.
        [InlineData(1, JapaneseHydrometerScaleUnit.ReciprocalSpecificGravity, 2, JapaneseHydrometerScaleUnit.ReciprocalSpecificGravity, false)] // Different value.
        public void Equals_ReturnsTrue_IfValueAndUnitAreEqual(double valueA, JapaneseHydrometerScaleUnit unitA, double valueB, JapaneseHydrometerScaleUnit unitB, bool expectEqual)
        {
            var a = new JapaneseHydrometerScale(valueA, unitA);
            var b = new JapaneseHydrometerScale(valueB, unitB);

            // Operator overloads.
            Assert.Equal(expectEqual, a == b);
            Assert.Equal(expectEqual, b == a);
            Assert.Equal(!expectEqual, a != b);
            Assert.Equal(!expectEqual, b != a);

            // IEquatable<T>
            Assert.Equal(expectEqual, a.Equals(b));
            Assert.Equal(expectEqual, b.Equals(a));

            // IEquatable
            Assert.Equal(expectEqual, a.Equals((object)b));
            Assert.Equal(expectEqual, b.Equals((object)a));
        }

        [Fact]
