        {
            // Chose this culture, because we don't currently have any abbreviations mapped for that culture and we expect the en-US to be used as fallback.
            var swedishCulture = CultureInfo.GetCultureInfo("sv-SE");

            Assert.Equal("1 °Bé heavy", new JapaneseHydrometerScale(1, JapaneseHydrometerScaleUnit.DegreeBaumeHeavy).ToString(swedishCulture));
            Assert.Equal("1 °Bé light", new JapaneseHydrometerScale(1, JapaneseHydrometerScaleUnit.DegreeBaumeLight).ToString(swedishCulture));
            Assert.Equal("1 1/SG", new JapaneseHydrometerScale(1, JapaneseHydrometerScaleUnit.ReciprocalSpecificGravity).ToString(swedishCulture));
            Assert.Equal("1 SMV", new JapaneseHydrometerScale(1, JapaneseHydrometerScaleUnit.SakeMeterValue).ToString(swedishCulture));
        }

